begin;
insert into auth.users(id)values('99000000-0000-4000-8000-000000000033'),('98000000-0000-4000-8000-000000000033');
select set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000033',true);
update private.ai_runtime set server_token_hash=sha256(convert_to('city-fixture-proof','UTF8')),pricing_verified=current_date;
create temporary table city_fixture(country uuid,city uuid,page uuid,foreign_country uuid,foreign_city uuid);
insert into city_fixture(country)select public.manage_country(null,'Pakistan');
update city_fixture set city=public.manage_city(null,country,'Mirpur - Area 25');
update city_fixture set page=public.create_location_page('Mirpur salons','',country,null);
insert into public.leads(page_id,business_name,phone)select page,'City lead fixture','123' from city_fixture;
select set_config('request.jwt.claim.sub','98000000-0000-4000-8000-000000000033',true);
update city_fixture set foreign_country=public.manage_country(null,'Pakistan');
update city_fixture set foreign_city=public.manage_city(null,foreign_country,'Mirpur');
select set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000033',true);
grant select on city_fixture to authenticated;
set local role authenticated;
do $$declare f record;r jsonb;op uuid;req uuid=gen_random_uuid();stamp timestamptz;payload jsonb;batch jsonb;city2 uuid;begin
 select * into f from city_fixture;
 if (select count(*) from public.lead_cities)<>1 then raise exception 'City RLS isolation failed';end if;
 begin perform public.manage_city(null,f.country,' MIRPUR - area 25 ');raise exception 'BAD duplicate';exception when unique_violation then null;end;
 begin perform public.move_page_location(f.page,f.country,f.foreign_city);raise exception 'BAD foreign move';exception when raise_exception then if sqlerrm='BAD foreign move' then raise;end if;end;
 begin perform public.manage_city(f.foreign_city,f.country,'Foreign edit');raise exception 'BAD foreign edit';exception when raise_exception then if sqlerrm='BAD foreign edit' then raise;end if;end;
 perform public.move_page_location(f.page,f.country,f.city);
 if not exists(select 1 from public.lead_pages where id=f.page and city_id=f.city) then raise exception 'City move failed';end if;
 r=public.country_structure();if jsonb_array_length(r->'cities')<>1 or not exists(select 1 from jsonb_array_elements(r->'assignments') a where (a->>'id')::uuid=f.page and (a->>'city_id')::uuid=f.city)then raise exception 'City structure failed';end if;
 perform public.move_country_page(f.page,null);if exists(select 1 from public.lead_pages where id=f.page and city_id is not null) then raise exception 'Moving country retained wrong city';end if;
 perform public.move_page_location(f.page,f.country,null);
 r=public.ai_stage_page_location(req,f.page,f.city,'city-fixture-proof');op=(r->>'id')::uuid;
 if r->>'status'<>'planned' or r->>'requiresApproval'<>'true' or r->'folderMove'->>'pageName'<>'Mirpur salons' then raise exception 'Folder preview failed';end if;
 if (public.ai_stage_page_location(req,f.page,f.city,'city-fixture-proof')->>'id')::uuid<>op then raise exception 'Folder plan retry failed';end if;
 begin perform public.ai_execute(op,false,'city-fixture-proof');raise exception 'BAD no approval';exception when raise_exception then if sqlerrm='BAD no approval' then raise;end if;end;
 r=public.ai_execute(op,true,'city-fixture-proof');if r->>'status'<>'completed' then raise exception 'Folder execution failed';end if;
 perform public.ai_execute(op,true,'city-fixture-proof');
 if not exists(select 1 from public.lead_pages where id=f.page and city_id=f.city) or (select count(*) from public.leads where page_id=f.page)<>1 or exists(select 1 from public.call_attempts where lead_id in(select id from public.leads where page_id=f.page)) then raise exception 'Folder move touched lead/call data';end if;
 r=public.ai_stage_page_location(gen_random_uuid(),f.page,f.city,'city-fixture-proof');op=(r->>'id')::uuid;
 perform public.manage_page(f.page,'Renamed salons','',false);
 begin perform public.ai_execute(op,true,'city-fixture-proof');raise exception 'BAD stale page';exception when raise_exception then if sqlerrm='BAD stale page' then raise;end if;end;
 r=public.ai_stage_page_location(gen_random_uuid(),f.page,f.city,'city-fixture-proof');op=(r->>'id')::uuid;
 perform public.manage_city(f.city,f.country,'Mirpur renamed');
 begin perform public.ai_execute(op,true,'city-fixture-proof');raise exception 'BAD stale city';exception when raise_exception then if sqlerrm='BAD stale city' then raise;end if;end;
 r=public.ai_stage_page_location(gen_random_uuid(),f.page,f.city,'city-fixture-proof');op=(r->>'id')::uuid;perform public.ai_cancel(op);
 begin perform public.ai_execute(op,true,'city-fixture-proof');raise exception 'BAD cancelled';exception when raise_exception then if sqlerrm='BAD cancelled' then raise;end if;end;
 begin perform public.ai_stage_page_location(gen_random_uuid(),f.page,f.foreign_city,'city-fixture-proof');raise exception 'BAD foreign stage';exception when raise_exception then if sqlerrm='BAD foreign stage' then raise;end if;end;
 payload=jsonb_build_object('p_request',gen_random_uuid(),'p_page',null,'p_new_name','City import','p_mode','new','p_file','city.csv','p_rows',jsonb_build_array(jsonb_build_object('business_name','City import lead','phone','555')),'p_total',1,'p_invalid',0);
 batch=public.import_in_location(f.country,f.city,payload);
 if not exists(select 1 from public.lead_pages where id=(batch->>'pageId')::uuid and city_id=f.city) then raise exception 'City import failed';end if;
 city2=public.manage_city(null,f.country,'Other area');perform public.import_in_location(f.country,city2,payload);
 if not exists(select 1 from public.lead_pages where id=(batch->>'pageId')::uuid and city_id=f.city) then raise exception 'Import retry moved destination';end if;
 perform public.manage_city(f.city,f.country,'',true);
 if exists(select 1 from public.lead_pages where city_id=f.city) or (select count(*) from public.leads)<>2 then raise exception 'City removal lost records';end if;
 perform public.move_page_location(f.page,f.country,city2);perform public.manage_country(f.country,'',true);
 if exists(select 1 from public.lead_cities where country_id=f.country) or exists(select 1 from public.lead_pages where country_id=f.country or city_id=city2) then raise exception 'Country deletion hierarchy failed';end if;
 raise notice 'PASS: custom cities, ownership, folder moves, frozen AI approval, stale/cancel guards, imports and non-destructive removal';
end $$;
rollback;
